Run status
One-line health summary per run: how many of the 64 detectors had peak 8 out of range (saturated at the 4,194,304 ceiling). A non-zero count means that detector’s brightest signal can’t be trusted on that day, and any intensity/SI metric derived from it is suspect.

Code
status &lt;- combined |&gt;
  filter(peak == n_peaks) |&gt;
  group_by(date) |&gt;
  summarise(saturated = sum(!in_range), total = n(), .groups = "drop") |&gt;
  arrange(date)

for (i in seq_len(nrow(status))) {
  r    &lt;- status[i, ]
  cls  &lt;- if (r$saturated == 0) "callout-note" else "callout-warning"
  cat(sprintf("::: {.%s}\n**Run %s** — %d / %d detectors saturated at peak 8.\n:::\n\n",
              cls, format(r$date), r$saturated, r$total))
}







